import React, { useState, useRef } from "react";
import { Card, CardFooter, CardHeader } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { X, Paperclip, Trash2 } from "lucide-react";
import { EmailMultiSelect, EmailOption } from "./email-multi-select";
import { EmailEditor } from "./custom-editor";
import { EmailPreview } from "./email-preview";
import { transformToEmailHtml } from "../../lib/email-transformer";

// Define types for attachments
interface Attachment {
  file: File;
  previewUrl?: string;
}

export function EmailComposer() {
  const [to, setTo] = useState<EmailOption[]>([]);
  const [cc, setCc] = useState<EmailOption[]>([]);
  const [bcc, setBcc] = useState<EmailOption[]>([]);
  const [subject, setSubject] = useState("");
  const [content, setContent] = useState("");
  const [showCc, setShowCc] = useState(false);
  const [showBcc, setShowBcc] = useState(false);
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [showPreview, setShowPreview] = useState(false);
  const [isTransforming, setIsTransforming] = useState(false);
  const [emailHtml, setEmailHtml] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSend = async () => {
    setIsTransforming(true);

    try {
      // Transform the TipTap content to email-safe HTML
      const transformedHtml = await transformToEmailHtml(content);
      setEmailHtml(transformedHtml);

      console.log({
        to,
        cc,
        bcc,
        subject,
        html: transformedHtml, // Use the transformed HTML for sending
        text: content.replace(/<[^>]*>/g, ""), // Plain text fallback
        attachments: attachments.map((att) => att.file),
      });

      // Clear the form
      setTo([]);
      setCc([]);
      setBcc([]);
      setSubject("");
      setContent("");
      setAttachments([]);
      setShowCc(false);
      setShowBcc(false);
      setEmailHtml(null);
    } catch (error) {
      console.error("Error transforming email content:", error);
    } finally {
      setIsTransforming(false);
    }
  };

  const handleAttachFile = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const newAttachments: Attachment[] = [];

    Array.from(files).forEach((file) => {
      const attachment: Attachment = { file };

      // Create preview URL for images
      if (file.type.startsWith("image/")) {
        attachment.previewUrl = URL.createObjectURL(file);
      }

      newAttachments.push(attachment);
    });

    setAttachments((prev) => [...prev, ...newAttachments]);

    // Reset the file input
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const removeAttachment = (index: number) => {
    setAttachments((prev) => {
      const newAttachments = [...prev];
      // Revoke the URL to avoid memory leaks
      if (newAttachments[index].previewUrl) {
        URL.revokeObjectURL(newAttachments[index].previewUrl!);
      }
      newAttachments.splice(index, 1);
      return newAttachments;
    });
  };

  // Format file size
  const formatFileSize = (bytes: number): string => {
    if (bytes < 1024) return bytes + " B";
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
    return (bytes / (1024 * 1024)).toFixed(1) + " MB";
  };

  return (
    <Card className="w-full h-auto">
      <CardHeader className="px-4 py-3 flex flex-row items-center justify-between">
        <div className="space-y-2 w-full">
          <div className="flex items-center justify-between">
            <div className="flex items-center w-full">
              <Badge variant="secondary" className="min-w-[35px] mr-2">
                To
              </Badge>
              <EmailMultiSelect
                placeholder="Enter recipients"
                options={[]}
                value={to}
                onChange={setTo}
                inputClassName="border-0 shadow-none rounded-none px-0 focus-visible:ring-0"
                containerClassName="w-full"
              />
            </div>
            <div className="flex items-center space-x-2">
              <div className="flex space-x-1">
                <button
                  type="button"
                  className={`text-xs px-2 py-1 rounded ${showCc ? "bg-muted text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                  onClick={() => setShowCc(!showCc)}
                >
                  Cc
                </button>
                <button
                  type="button"
                  className={`text-xs px-2 py-1 rounded ${showBcc ? "bg-muted text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                  onClick={() => setShowBcc(!showBcc)}
                >
                  Bcc
                </button>
              </div>
              <Button
                variant="ghost"
                size="icon"
                className="ml-auto"
                onClick={() => {
                  // Clear form and attachments
                  setTo([]);
                  setCc([]);
                  setBcc([]);
                  setSubject("");
                  setContent("");
                  setShowCc(false);
                  setShowBcc(false);
                  // Clean up attachments
                  attachments.forEach((attachment) => {
                    if (attachment.previewUrl) {
                      URL.revokeObjectURL(attachment.previewUrl);
                    }
                  });
                  setAttachments([]);
                }}
              >
                <X className="h-4 w-4" />
              </Button>
            </div>
          </div>

          {showCc && (
            <div className="flex items-center w-full border-t pt-2">
              <Badge
                variant="outline"
                className="min-w-[35px] mr-2 border-blue-200 text-blue-500"
              >
                Cc
              </Badge>
              <EmailMultiSelect
                placeholder="Enter Cc recipients"
                options={[]}
                value={cc}
                onChange={setCc}
                inputClassName="border-0 shadow-none rounded-none px-0 focus-visible:ring-0"
                containerClassName="w-full"
              />
            </div>
          )}

          {showBcc && (
            <div className="flex items-center w-full border-t pt-2">
              <Badge
                variant="outline"
                className="min-w-[35px] mr-2 border-purple-200 text-purple-500"
              >
                Bcc
              </Badge>
              <EmailMultiSelect
                placeholder="Enter Bcc recipients"
                options={[]}
                value={bcc}
                onChange={setBcc}
                inputClassName="border-0 shadow-none rounded-none px-0 focus-visible:ring-0"
                containerClassName="w-full"
              />
            </div>
          )}

          <div className="flex items-center w-full border-y pt-2">
            <Badge
              variant="outline"
              className="min-w-[35px] mr-2 border-green-200 text-green-500"
            >
              Subject
            </Badge>
            <Input
              placeholder="Enter subject"
              value={subject}
              onChange={(e) => setSubject(e.target.value)}
              className="border-0 px-0 shadow-none rounded-none focus-visible:ring-0"
            />
          </div>
        </div>
      </CardHeader>

      <div className="px-4 py-0">
        <EmailEditor
          content={content}
          onChange={setContent}
          placeholder="Write your email here..."
          className="min-h-[200px] focus-visible:outline-none"
        />

        {/* Attachments Section */}
        <div className="py-2">
          {attachments.length > 0 && (
            <div className="border rounded-md p-2 mt-2">
              <div className="text-sm font-medium mb-2">Attachments</div>
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
                {attachments.map((attachment, index) => (
                  <div
                    key={`${attachment.file.name}-${index}`}
                    className="relative border rounded-md p-2 flex flex-col"
                  >
                    <button
                      type="button"
                      onClick={() => removeAttachment(index)}
                      className="absolute top-1 right-1 bg-background hover:bg-muted rounded-full p-1 shadow-sm border z-10"
                      aria-label={`Remove ${attachment.file.name}`}
                    >
                      <X className="h-4 w-4" />
                    </button>
                    <div className="relative h-20 w-full">
                      {attachment.file.type.startsWith("image/") &&
                      attachment.previewUrl ? (
                        // eslint-disable-next-line @next/next/no-img-element
                        <img
                          src={attachment.previewUrl}
                          alt={attachment.file.name}
                          className="h-full w-full object-cover rounded-md"
                        />
                      ) : (
                        <div className="flex items-center justify-center h-full w-full bg-muted rounded-md">
                          <div className="text-2xl font-bold uppercase text-muted-foreground">
                            {attachment.file.name
                              .split(".")
                              .pop()
                              ?.substring(0, 3) || "?"}
                          </div>
                        </div>
                      )}
                    </div>
                    <div className="mt-1 text-xs truncate">
                      {attachment.file.name}
                    </div>
                    <div className="text-xs text-muted-foreground">
                      {formatFileSize(attachment.file.size)}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      <CardFooter className="flex justify-start gap-x-2 items-center p-3 border-t">
        <Button
          onClick={handleSend}
          className="bg-blue-600 hover:bg-blue-700 text-white"
          disabled={isTransforming}
        >
          {isTransforming ? (
            <>
              <span className="mr-2">Preparing...</span>
              <span className="animate-spin">↻</span>
            </>
          ) : (
            "Send"
          )}
        </Button>
        <Button
          variant="outline"
          onClick={() => setShowPreview(true)}
          className="text-muted-foreground"
          disabled={!content}
        >
          Preview
        </Button>
        <div className="flex items-center">
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileChange}
            className="hidden"
            multiple
          />
          <Button
            variant="outline"
            size="icon"
            className="text-muted-foreground"
            onClick={handleAttachFile}
            title="Attach files"
          >
            <Paperclip className="h-4 w-4" />
          </Button>
        </div>
        <Button
          variant="ghost"
          size="icon"
          className="text-muted-foreground"
          onClick={() => {
            // Clear all attachments and revoke their object URLs to avoid memory leaks
            attachments.forEach((attachment) => {
              if (attachment.previewUrl) {
                URL.revokeObjectURL(attachment.previewUrl);
              }
            });
            setAttachments([]);
          }}
          disabled={attachments.length === 0}
          title="Clear all attachments"
        >
          <Trash2 className="h-4 w-4" />
        </Button>
      </CardFooter>

      {/* Email Preview Dialog */}
      <EmailPreview
        content={content}
        isOpen={showPreview}
        onClose={() => setShowPreview(false)}
      />
    </Card>
  );
}

import "../../editor.css";

import { useEditor, EditorContent, BubbleMenu, Extension } from "@tiptap/react";
import StarterKit from "@tiptap/starter-kit";
import Placeholder from "@tiptap/extension-placeholder";
import Link from "@tiptap/extension-link";
import Image from "@tiptap/extension-image";
import TextAlign from "@tiptap/extension-text-align";
import Underline from "@tiptap/extension-underline";
import Color from "@tiptap/extension-color";
import TextStyle from "@tiptap/extension-text-style";
import { type ClassValue } from "clsx";
import { cn } from "@/lib/utils";
import {
  Bold,
  Italic,
  Underline as UnderlineIcon,
  List,
  ListOrdered,
  Link as LinkIcon,
  AlignLeft,
  AlignCenter,
  AlignRight,
  Quote,
  Palette,
  Highlighter,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";

// Create a custom extension for background color
const BackgroundColor = Extension.create({
  name: "backgroundColor",

  addOptions() {
    return {
      types: ["textStyle"],
    };
  },

  addGlobalAttributes() {
    return [
      {
        types: this.options.types,
        attributes: {
          backgroundColor: {
            default: null,
            parseHTML: (element: any) => element.style.backgroundColor,
            renderHTML: (attributes: any) => {
              if (!attributes.backgroundColor) {
                return {};
              }

              return {
                style: `background-color: ${attributes.backgroundColor}`,
              };
            },
          },
        },
      },
    ];
  },

  addCommands() {
    return {
      setBackgroundColor:
        (color: any) =>
        ({ chain }: any) => {
          return chain().setMark("textStyle", { backgroundColor: color }).run();
        },
      unsetBackgroundColor:
        () =>
        ({ chain }: any) => {
          return chain()
            .setMark("textStyle", { backgroundColor: null })
            .removeEmptyTextStyle()
            .run();
        },
    };
  },
} as any);

// Text and background colors
const TEXT_COLORS = [
  { color: "#000000", name: "Black" },
  { color: "#333333", name: "Dark Gray" },
  { color: "#666666", name: "Gray" },
  { color: "#1a73e8", name: "Blue" },
  { color: "#d93025", name: "Red" },
  { color: "#188038", name: "Green" },
  { color: "#f9ab00", name: "Yellow" },
  { color: "#a142f4", name: "Purple" },
];

const BACKGROUND_COLORS = [
  { color: "#ffffff", name: "White" },
  { color: "#f1f3f4", name: "Light Gray" },
  { color: "#d2e3fc", name: "Light Blue" },
  { color: "#fce8e6", name: "Light Red" },
  { color: "#e6f4ea", name: "Light Green" },
  { color: "#fef7e0", name: "Light Yellow" },
  { color: "#f3e8fd", name: "Light Purple" },
];

// Enhanced bubble menu with quote option
function EnhancedBubbleMenu({
  editor,
}: {
  editor: ReturnType<typeof useEditor>;
}) {
  const [showTextColors, setShowTextColors] = useState(false);
  const [showBgColors, setShowBgColors] = useState(false);

  if (!editor) return null;

  return (
    <div className="flex flex-col items-start gap-1 rounded-lg border bg-background p-1 shadow-md max-w-[280px]">
      <div className="flex flex-wrap items-center gap-1">
        <MenuButton
          isActive={editor.isActive("bold")}
          onClick={() => editor.chain().focus().toggleBold().run()}
        >
          <Bold className="h-4 w-4" />
        </MenuButton>
        <MenuButton
          isActive={editor.isActive("italic")}
          onClick={() => editor.chain().focus().toggleItalic().run()}
        >
          <Italic className="h-4 w-4" />
        </MenuButton>
        <MenuButton
          isActive={editor.isActive("underline")}
          onClick={() => editor.chain().focus().toggleUnderline().run()}
        >
          <UnderlineIcon className="h-4 w-4" />
        </MenuButton>
        <div className="w-[1px] h-4 bg-border mx-1" />
        <MenuButton
          isActive={editor.isActive("bulletList")}
          onClick={() => editor.chain().focus().toggleBulletList().run()}
        >
          <List className="h-4 w-4" />
        </MenuButton>
        <MenuButton
          isActive={editor.isActive("orderedList")}
          onClick={() => editor.chain().focus().toggleOrderedList().run()}
        >
          <ListOrdered className="h-4 w-4" />
        </MenuButton>
        {/* Add blockquote button */}
        <MenuButton
          isActive={editor.isActive("blockquote")}
          onClick={() => editor.chain().focus().toggleBlockquote().run()}
        >
          <Quote className="h-4 w-4" />
        </MenuButton>
        <div className="w-[1px] h-4 bg-border mx-1" />
        <MenuButton
          isActive={editor.isActive({ textAlign: "left" })}
          onClick={() => editor.chain().focus().setTextAlign("left").run()}
        >
          <AlignLeft className="h-4 w-4" />
        </MenuButton>
        <MenuButton
          isActive={editor.isActive({ textAlign: "center" })}
          onClick={() => editor.chain().focus().setTextAlign("center").run()}
        >
          <AlignCenter className="h-4 w-4" />
        </MenuButton>
        <MenuButton
          isActive={editor.isActive({ textAlign: "right" })}
          onClick={() => editor.chain().focus().setTextAlign("right").run()}
        >
          <AlignRight className="h-4 w-4" />
        </MenuButton>
        <div className="w-[1px] h-4 bg-border mx-1" />
        <MenuButton
          isActive={editor.isActive("link")}
          onClick={() => {
            const previousUrl = editor.getAttributes("link").href;
            const url = window.prompt("URL", previousUrl);
            if (url === null) return;
            if (url === "") {
              editor.chain().focus().unsetLink().run();
              return;
            }
            editor.chain().focus().setLink({ href: url }).run();
          }}
        >
          <LinkIcon className="h-4 w-4" />
        </MenuButton>
        <MenuButton
          isActive={false}
          onClick={() => setShowTextColors(!showTextColors)}
        >
          <Palette className="h-4 w-4" />
        </MenuButton>
        <MenuButton
          isActive={false}
          onClick={() => setShowBgColors(!showBgColors)}
        >
          <Highlighter className="h-4 w-4" />
        </MenuButton>
      </div>

      {showTextColors && (
        <div className="flex flex-wrap gap-1 p-1 border-t pt-1 w-full">
          <ColorButton
            color="inherit"
            isActive={!editor.getAttributes("textStyle").color}
            onClick={() => {
              editor.chain().focus().unsetColor().run();
              setShowTextColors(false);
            }}
          />
          {TEXT_COLORS.map((color) => (
            <ColorButton
              key={color.color}
              color={color.color}
              isActive={editor.isActive("textStyle", { color: color.color })}
              onClick={() => {
                editor.chain().focus().setColor(color.color).run();
                setShowTextColors(false);
              }}
            />
          ))}
        </div>
      )}

      {showBgColors && (
        <div className="flex flex-wrap gap-1 p-1 border-t pt-1 w-full">
          <ColorButton
            color="inherit"
            isActive={!editor.getAttributes("textStyle").backgroundColor}
            onClick={() => {
              editor
                .chain()
                .focus()
                .setMark("textStyle", { backgroundColor: null })
                .removeEmptyTextStyle()
                .run();
              setShowBgColors(false);
            }}
          />
          {BACKGROUND_COLORS.map((color) => (
            <ColorButton
              key={color.color}
              color={color.color}
              isActive={editor.isActive("textStyle", {
                backgroundColor: color.color,
              })}
              onClick={() => {
                editor
                  .chain()
                  .focus()
                  .setMark("textStyle", { backgroundColor: color.color })
                  .run();
                setShowBgColors(false);
              }}
            />
          ))}
        </div>
      )}
    </div>
  );
}

function MenuButton({
  children,
  isActive,
  onClick,
}: {
  children: React.ReactNode;
  isActive: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      className={cn(
        "flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground",
        isActive && "bg-accent text-accent-foreground"
      )}
      onClick={onClick}
    >
      {children}
    </button>
  );
}

function ColorButton({
  color,
  isActive,
  onClick,
}: {
  color: string;
  isActive: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      className={cn(
        "w-5 h-5 rounded-md border border-muted",
        isActive && "ring-2 ring-primary ring-offset-1"
      )}
      style={{ backgroundColor: color }}
      onClick={onClick}
      title={color}
    />
  );
}

interface EmailEditorProps {
  className?: ClassValue;
  content?: string;
  onChange: (content: string) => void;
  placeholder?: string;
  onEditorReady?: (editor: ReturnType<typeof useEditor>) => void;
  showBubbleMenu?: boolean;
}

export function EmailEditor({
  className,
  content = "",
  onChange,
  placeholder = "Write something...",
  onEditorReady,
  showBubbleMenu = true,
}: EmailEditorProps) {
  const editorRef = useRef<ReturnType<typeof useEditor> | null>(null);

  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: {
          levels: [1, 2, 3],
        },
      }),
      Placeholder.configure({
        placeholder,
        emptyEditorClass: "is-editor-empty",
      }),
      Underline,
      TextAlign.configure({
        types: ["heading", "paragraph"],
      }),
      Link.configure({
        openOnClick: false,
      }),
      Image.configure({
        HTMLAttributes: {
          class: "max-w-full rounded-md border-2 border-blue-400 mx-auto",
        },
      }),
      Color.configure({
        types: ["textStyle"],
      }),
      TextStyle,
      BackgroundColor,
    ],
    content,
    editorProps: {
      attributes: {
        class: cn("prose prose-sm focus:outline-none max-w-none", className),
      },
    },
    onUpdate: ({ editor }) => {
      onChange(editor.getHTML());
    },
    // Set immediatelyRender to false to prevent SSR hydration issues
    immediatelyRender: false,
  });

  useEffect(() => {
    if (editor && onEditorReady) {
      onEditorReady(editor);
    }
    editorRef.current = editor;
  }, [editor, onEditorReady]);

  return (
    <div className="w-full relative">
      <EditorContent editor={editor} className="w-full" />
      {editor && showBubbleMenu && (
        <BubbleMenu
          editor={editor}
          tippyOptions={{
            duration: 100,
            placement: "top",
            maxWidth: "none",
          }}
          shouldShow={({ state, from, to }) => {
            const { doc, selection } = state;
            const { empty } = selection;
            const isEmptyTextBlock = !doc.textBetween(from, to).length;
            return !empty && !isEmptyTextBlock;
          }}
        >
          <EnhancedBubbleMenu editor={editor} />
        </BubbleMenu>
      )}
    </div>
  );
}

import React, { useState, useRef, useEffect, KeyboardEvent } from "react";
import { Button } from "@/components/ui/button";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";

export interface EmailOption {
  value: string;
  label: string;
  avatar?: string;
}

interface EmailMultiSelectProps {
  placeholder?: string;
  options: EmailOption[];
  value: EmailOption[];
  onChange: (value: EmailOption[]) => void;
  containerClassName?: string;
  inputClassName?: string;
}

export function EmailMultiSelect({
  placeholder = "Recipients",
  options = [],
  value = [],
  onChange,
  containerClassName,
  inputClassName,
}: EmailMultiSelectProps) {
  const [inputValue, setInputValue] = useState("");
  const [showOptions, setShowOptions] = useState(false);
  const [filteredOptions, setFilteredOptions] = useState<EmailOption[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Filter options based on input value and exclude already selected options
  useEffect(() => {
    if (inputValue.trim() === "") {
      setFilteredOptions([]);
    } else {
      const filtered = options.filter(
        (option) =>
          option.label.toLowerCase().includes(inputValue.toLowerCase()) &&
          !value.some((v) => v.value === option.value)
      );
      setFilteredOptions(filtered);
    }
  }, [inputValue, options, value]);

  // Click outside to close options
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node) &&
        inputRef.current &&
        !inputRef.current.contains(event.target as Node)
      ) {
        setShowOptions(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(e.target.value);
    if (e.target.value.trim() !== "") {
      setShowOptions(true);
    } else {
      setShowOptions(false);
    }
  };

  const handleInputKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    // Add email on Enter if it looks like an email
    if (e.key === "Enter" && inputValue.trim() !== "") {
      e.preventDefault();

      // Simple email validation
      const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(inputValue);

      if (isValidEmail) {
        const newOption: EmailOption = {
          value: inputValue,
          label: inputValue,
        };

        onChange([...value, newOption]);
        setInputValue("");
      }
    }
    // Remove the last tag on Backspace if input is empty
    else if (e.key === "Backspace" && inputValue === "" && value.length > 0) {
      const newValue = [...value];
      newValue.pop();
      onChange(newValue);
    }
  };

  const handleSelectOption = (option: EmailOption) => {
    onChange([...value, option]);
    setInputValue("");
    setShowOptions(false);
    inputRef.current?.focus();
  };

  const handleRemoveOption = (optionToRemove: EmailOption) => {
    onChange(value.filter((option) => option.value !== optionToRemove.value));
  };

  const handleAddManualEmail = () => {
    if (inputValue.trim() !== "") {
      // Simple email validation
      const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(inputValue);

      if (isValidEmail) {
        const newOption: EmailOption = {
          value: inputValue,
          label: inputValue,
        };

        onChange([...value, newOption]);
        setInputValue("");
        setShowOptions(false);
      }
    }
  };

  return (
    <div className={cn("relative", containerClassName)}>
      <div className="flex flex-wrap items-center gap-1">
        {value.map((option) => (
          <div
            key={option.value}
            className="flex items-center gap-1.5 bg-muted text-muted-foreground text-sm rounded-full pl-3 pr-2 py-1"
          >
            <span>{option.label}</span>
            <button
              type="button"
              onClick={() => handleRemoveOption(option)}
              className="text-muted-foreground hover:text-foreground rounded-full"
            >
              <X className="h-3 w-3" />
            </button>
          </div>
        ))}
        <input
          ref={inputRef}
          type="text"
          value={inputValue}
          onChange={handleInputChange}
          onKeyDown={handleInputKeyDown}
          onFocus={() => inputValue.trim() !== "" && setShowOptions(true)}
          placeholder={value.length === 0 ? placeholder : ""}
          className={cn("flex-1 outline-none min-w-[120px]", inputClassName)}
        />
      </div>

      {showOptions && (
        <div
          ref={dropdownRef}
          className="absolute top-full left-0 z-50 w-full mt-1 bg-background rounded-md border shadow-md max-h-60 overflow-auto"
        >
          {filteredOptions.length > 0 ? (
            <div>
              {filteredOptions.map((option) => (
                <div
                  key={option.value}
                  className="flex items-center px-3 py-2 hover:bg-muted cursor-pointer"
                  onClick={() => handleSelectOption(option)}
                >
                  {option.avatar && (
                    <div className="w-6 h-6 rounded-full bg-muted-foreground mr-2" />
                  )}
                  <span>{option.label}</span>
                </div>
              ))}
            </div>
          ) : (
            inputValue.trim() !== "" && (
              <div
                className="flex items-center justify-between px-3 py-2 hover:bg-muted cursor-pointer"
                onClick={handleAddManualEmail}
              >
                <span>{`Add "${inputValue}"`}</span>
                <span className="text-sm text-muted-foreground">Enter ↵</span>
              </div>
            )
          )}
        </div>
      )}
    </div>
  );
}

